        jQuery(document).ready(function($) {
            var emailModal = $('#EmailModal');
            var emailModalBackdrop = $('#EmailModalBackdrop');

            function showEmailModal() {
                emailModalBackdrop.addClass('show');
                emailModal.addClass('show');
                $('body').addClass('modal-open');
            }

            function hideEmailModal() {
                emailModal.removeClass('show');
                emailModalBackdrop.removeClass('show');
                setTimeout(function() {
                    $('body').removeClass('modal-open');
                }, 500);
            }
            $(document).on('click', '[data-target="#EmailModal"]', function(e) {
                e.preventDefault();
                showEmailModal();
            });
            $(document).on('click', '.modal-dropdown-btn, .icon-drop-close-icon', function(e) {
                e.preventDefault();
                hideEmailModal();
            });
            $(document).on('click', '#EmailModal, #EmailModalBackdrop', function(e) {
                if (e.target === this) {
                    hideEmailModal();
                }
            });
            $(document).on('keydown', function(e) {
                if (e.keyCode === 27 && (emailModal.hasClass('show') || emailModalBackdrop.hasClass('show'))) {
                    hideEmailModal();
                }
            });
            $(document).on('click', '#EmailModal .modal-content', function(e) {
                e.stopPropagation();
            });
            $(document).on('click', '#EmailModal .sideform-open', function(e) {
                hideEmailModal();
            });
        });

